Considere a consulta analítica que busca os 3 funcionários mais bem pagos de cada departamento:
SELECT id, nome, depto_id, salario FROM (
  SELECT id, nome, depto_id, salario, ROW_NUMBER() OVER (PARTITION BY depto_id ORDER BY salario DESC) AS rn FROM funcionarios
) t WHERE rn <= 3;
